// Bab 7 Data Modeling: model untuk BI dan pola modern (model semantik Power BI, OBT lawan star schema,
// Data Vault, lakehouse dengan Parquet dan Delta Lake, pratinjau dbt).
// Power BI tidak dijalankan di sini. Setiap konsep Power BI ditunjukkan padanannya dengan query SQL ke star schema.
// Setiap latihan dijalankan di transaksi yang dibatalkan, jadi dimensi dan fakta dibuat ulang di setup.

// Dimensi dan tabel fakta dari bab model-04, disalin persis (DIM_DATE, DIM_PRODUCT, DIM_CUSTOMER, EXTRA_ROWS, FACT_ORDER_LINE).
const DIM_DATE = `create schema dw;
create table dw.dim_date (
  date_key integer primary key,
  full_date date not null unique,
  year integer not null,
  quarter integer not null,
  month integer not null,
  month_name text not null,
  day_of_month integer not null,
  day_of_week integer not null,
  day_name text not null,
  is_weekend boolean not null
);
insert into dw.dim_date
with tanggal as (
  select g::date as d
  from generate_series(date '2024-01-01', date '2025-12-31', interval '1 day') as g
)
select to_char(d, 'YYYYMMDD')::integer, d,
       extract(year from d), extract(quarter from d), extract(month from d),
       to_char(d, 'FMMonth'), extract(day from d),
       extract(isodow from d), to_char(d, 'FMDay'),
       extract(isodow from d) in (6, 7)
from tanggal;`;

const DIM_PRODUCT = `create table dw.dim_product (
  product_sk integer generated by default as identity primary key,
  product_id integer not null unique,
  sku text not null,
  product_name text not null,
  brand text not null,
  category_name text not null,
  parent_category_name text not null,
  is_active boolean not null
);
insert into dw.dim_product (product_sk, product_id, sku, product_name, brand, category_name, parent_category_name, is_active)
values (-1, -1, 'Tidak diketahui', 'Produk tidak diketahui', 'Tidak diketahui', 'Tidak diketahui', 'Tidak diketahui', false);
insert into dw.dim_product (product_id, sku, product_name, brand, category_name, parent_category_name, is_active)
select p.product_id, p.sku, p.product_name, p.brand, c.category_name, pc.category_name, p.is_active
from app.products as p
join app.categories as c on c.category_id = p.category_id
join app.categories as pc on pc.category_id = c.parent_id
order by p.product_id
on conflict (product_id) do update
set sku = excluded.sku,
    product_name = excluded.product_name,
    brand = excluded.brand,
    category_name = excluded.category_name,
    parent_category_name = excluded.parent_category_name,
    is_active = excluded.is_active;`;

const DIM_CUSTOMER = `create table dw.dim_customer (
  customer_sk integer generated always as identity primary key,
  customer_id integer not null,
  full_name text not null,
  city_id integer not null,
  city_name text not null,
  segment text not null,
  valid_from date not null,
  valid_to date not null,
  is_current boolean not null
);
insert into dw.dim_customer (customer_id, full_name, city_id, city_name, segment, valid_from, valid_to, is_current)
with potret as (
  select snapshot_date, customer_id, full_name, city_id, segment,
         lag(city_id) over (partition by customer_id order by snapshot_date) as kota_sebelumnya,
         lag(segment) over (partition by customer_id order by snapshot_date) as segmen_sebelumnya
  from raw.customer_snapshot
),
awal_versi as (
  select snapshot_date, customer_id, full_name, city_id, segment
  from potret
  where kota_sebelumnya is null
     or city_id <> kota_sebelumnya
     or segment <> segmen_sebelumnya
),
versi as (
  select a.*,
         row_number() over (partition by customer_id order by snapshot_date) as nomor_versi,
         lead(snapshot_date) over (partition by customer_id order by snapshot_date) as awal_berikutnya
  from awal_versi as a
)
select v.customer_id, v.full_name, v.city_id, ci.city_name, v.segment,
       case when v.nomor_versi = 1 then cu.signup_date else v.snapshot_date end,
       coalesce(v.awal_berikutnya - 1, date '9999-12-31'),
       v.awal_berikutnya is null
from versi as v
join app.cities as ci on ci.city_id = v.city_id
join app.customers as cu on cu.customer_id = v.customer_id
order by v.customer_id, v.snapshot_date;`;

const EXTRA_ROWS = `insert into dw.dim_date
values (-1, date '9999-12-31', 9999, 4, 12, 'Belum terjadi', 31, 5, 'Belum terjadi', false);
insert into dw.dim_customer (customer_sk, customer_id, full_name, city_id, city_name, segment, valid_from, valid_to, is_current)
overriding system value
values (-1, -1, 'Pelanggan tidak diketahui', -1, 'Tidak diketahui', 'Tidak diketahui', date '1900-01-01', date '9999-12-31', true);`;

// Tambahan bab ini: provinsi dan pulau ikut disimpan di dimensi pelanggan, supaya laporan bisa menyaring
// menurut pulau tanpa JOIN tambahan ke app.cities. Nilainya mengikuti kota di setiap versi SCD tipe 2.
const CUSTOMER_GEO = `alter table dw.dim_customer add column province text, add column island text;
update dw.dim_customer as c
set province = ci.province, island = ci.island
from app.cities as ci
where ci.city_id = c.city_id;
update dw.dim_customer set province = 'Tidak diketahui', island = 'Tidak diketahui' where customer_sk = -1;`;

// Sama dengan FACT_ORDER_LINE di model-04, tanpa REFERENCES supaya pemuatan di browser lebih cepat.
const FACT_ORDER_LINE = `create table dw.fact_order_line (
  order_id integer not null,
  line_no integer not null,
  order_date_key integer not null,
  customer_sk integer not null,
  product_sk integer not null,
  qty integer not null,
  gross_amount numeric(14,2) not null,
  discount numeric(14,2) not null,
  net_amount numeric(14,2) not null,
  primary key (order_id, line_no)
);
insert into dw.fact_order_line
  (order_id, line_no, order_date_key, customer_sk, product_sk, qty, gross_amount, discount, net_amount)
select oi.order_id, oi.line_no,
       coalesce(d.date_key, -1),
       coalesce(c.customer_sk, -1),
       coalesce(p.product_sk, -1),
       oi.qty,
       oi.qty * oi.unit_price,
       oi.discount,
       oi.qty * oi.unit_price - oi.discount
from app.order_items as oi
join app.orders as o on o.order_id = oi.order_id
left join dw.dim_date as d on d.full_date = o.order_ts::date
left join dw.dim_customer as c
  on c.customer_id = o.customer_id
 and o.order_ts::date between c.valid_from and c.valid_to
left join dw.dim_product as p on p.product_id = oi.product_id;`;

const STAR = `${DIM_DATE}\n${DIM_PRODUCT}\n${DIM_CUSTOMER}\n${EXTRA_ROWS}\n${CUSTOMER_GEO}\n${FACT_ORDER_LINE}`;

// Satu tabel lebar (one big table): satu baris per baris pesanan, dengan atribut dimensi yang disalin ke setiap baris.
const OBT_SQL = `create schema mart;
create table mart.obt_order_line as
select f.order_id, f.line_no, d.full_date as order_date,
       c.customer_id, c.full_name as customer_name, c.segment, c.city_name, c.island,
       p.product_id, p.product_name, p.brand, p.parent_category_name,
       f.qty, f.gross_amount, f.discount, f.net_amount
from dw.fact_order_line as f
join dw.dim_date as d on d.date_key = f.order_date_key
join dw.dim_customer as c on c.customer_sk = f.customer_sk
join dw.dim_product as p on p.product_sk = f.product_sk;`;

const WITH_OBT = `${STAR}\n${OBT_SQL}`;

// Verify soal build OBT: dibaca mesin saja. Setiap kolom dicocokkan ulang ke star schema.
const VERIFY_OBT = `select count(*) as baris,
       count(*) - (select count(*) from dw.fact_order_line) as selisih_baris,
       count(distinct (o.order_id, o.line_no)) as grain_unik,
       sum(o.qty) as qty, sum(o.gross_amount) as gross, sum(o.discount) as diskon, sum(o.net_amount) as bersih,
       count(*) filter (where o.order_date = d.full_date) as tanggal_cocok,
       count(*) filter (where o.customer_id = c.customer_id and o.customer_name = c.full_name and o.segment = c.segment
                          and o.city_name = c.city_name and o.island = c.island) as pelanggan_cocok,
       count(*) filter (where o.product_id = p.product_id and o.product_name = p.product_name and o.brand = p.brand
                          and o.parent_category_name = p.parent_category_name) as produk_cocok,
       count(*) filter (where o.qty = f.qty and o.gross_amount = f.gross_amount and o.discount = f.discount
                          and o.net_amount = f.net_amount) as measure_cocok
from mart.obt_order_line as o
left join dw.fact_order_line as f on f.order_id = o.order_id and f.line_no = o.line_no
left join dw.dim_date as d on d.date_key = f.order_date_key
left join dw.dim_customer as c on c.customer_sk = f.customer_sk
left join dw.dim_product as p on p.product_sk = f.product_sk;`;

